#include "Common.hh"
int main(int argc,char**argv)try{
 using namespace mip;require(argc==4,"Usage: Export histograms.root fits.root output-directory");std::string out=argv[3];fresh(out+"/mip.root");
 auto hf=mmr::openFile(argv[1]),ff=mmr::openFile(argv[2]);auto meta=readMeta(*hf);auto results=readResults(*ff);require(meta.size()==6300&&results.size()==6300,"Expected one metadata/result row for each connected channel");
 TFile output((out+"/mip.root").c_str(),"CREATE");require(!output.IsZombie(),"Cannot create mip.root");TTree tree("MIP_Fit","Data-only Landau MPV; zero MPV/NDF marks unmeasured or rejected channels");
 int CellID=0,NDF=0,chnEntries=0;double LandauMPV=0,LandauWidth=0,GauSigma=0,ChiSquare=0,LandauMPV_error=0,LandauWidth_error=0,GauSigma_error=0;
#define B(v) tree.Branch(#v,&v)
 B(CellID);B(LandauMPV);B(LandauWidth);B(GauSigma);B(ChiSquare);B(NDF);B(chnEntries);B(LandauMPV_error);B(LandauWidth_error);B(GauSigma_error);
#undef B
 long double sums[2]={};int donors[2]={};
 for(auto&[id,r]:results){require(meta.count(id)&&mmr::physical(id)==id,"Unexpected result channel");CellID=id;chnEntries=r.chnEntries;NDF=0;LandauMPV=LandauWidth=GauSigma=ChiSquare=LandauMPV_error=LandauWidth_error=GauSigma_error=0;
 if(r.decision==1){require(std::isfinite(r.LandauMPV)&&r.LandauMPV>0&&r.NDF>0&&std::isfinite(r.ChiSquare)&&r.ChiSquare>=0&&r.ChiSquare/r.NDF<=(mmr::group(id)?2.:1.7),"Accepted result would fail reader");LandauMPV=r.LandauMPV;LandauWidth=r.LandauWidth;GauSigma=r.GauSigma;ChiSquare=r.ChiSquare;NDF=r.NDF;LandauMPV_error=r.LandauMPV_error;LandauWidth_error=r.LandauWidth_error;GauSigma_error=r.GauSigma_error;sums[mmr::group(id)]+=r.LandauMPV;++donors[mmr::group(id)];}
 tree.Fill();}
 tree.Write();TNamed("reference_definition","Pedestal subtracted HG ADC, normalized to 2 mm; temperature mode is recorded in inputs/configuration.tsv; current uses production C=1-alpha*(T-20), not an independently established physical 20C conversion. Crosstalk retained.").Write();TNamed("rejection","Every decision other than accepted_direct is LandauMPV=0,NDF=0. Candidate fits are in fits.root/Diagnostics, never replaced by individual fake measurements.").Write();output.Close();
 double means[2]={donors[0]?double(sums[0]/donors[0]):mip::nan,donors[1]?double(sums[1]/donors[1]):mip::nan};bool ready=donors[0]>0&&donors[1]>0;
 // Read the actual generated tree back with the shared current-reader policy.
 if(ready){auto adopted=mmr::loadMip(out+"/mip.root");for(auto&[id,p]:adopted){auto&r=results.at(id);require(p.mipFallback==(r.decision!=1),"Reader rejection propagation failed");require(std::abs(p.mip-(r.decision==1?r.LandauMPV:means[mmr::group(id)]))<1e-10,"Reader effective constant mismatch");}}
 auto check=mmr::openFile(out+"/mip.root");auto*t=dynamic_cast<TTree*>(check->Get("MIP_Fit"));require(t&&t->GetEntries()==6300,"Invalid compatibility tree size");std::ofstream schema(out+"/schema.tsv");schema<<"branch\ttype\n";
 for(auto name:{"CellID","LandauMPV","LandauWidth","GauSigma","ChiSquare","NDF","chnEntries","LandauMPV_error","LandauWidth_error","GauSigma_error"}){auto*l=t->GetLeaf(name);std::string expected=(std::string(name)=="CellID"||std::string(name)=="NDF"||std::string(name)=="chnEntries")?"Int_t":"Double_t";require(l&&l->GetTypeName()==expected,"Wrong branch type");schema<<name<<'\t'<<l->GetTypeName()<<'\n';}
 std::ofstream table(out+"/channels.tsv"),summary(out+"/summary.tsv"),state(out+"/reader_status.tsv");
 table<<"CellID\tSiPM_um\tlayer\tchip\tdecision\treason\tpredicted\tobserved\tunique\tusable\tacquisition_efficiency\tunique_efficiency\tefficiency_binomial_SE\tduplicate\tswitched_HG2600\tforced_HG4000\tHG_saturated\tLG_saturated\tgain0\tinvalid_ADC\tmissing_temperature\tinvalid_temperature\tpedestal\tthreshold\tthreshold_sigma\tthreshold_fallback\told_individual\told_effective_MIP\tnew_individual\tnew_effective_MIP\tnew_over_old\tcandidate_MPV\tcandidate_MPV_error\n";
 struct Sum{int channels=0,old_individual=0,accepted=0,undecided=0,rejected=0;Long64_t predicted=0,observed=0;};std::map<std::tuple<int,int,int,int>,Sum>summaryMap;
 for(auto&[id,m]:meta){auto&r=results.at(id);int g=mmr::group(id),sipm=g?10:15;double effective=r.decision==1?r.LandauMPV:means[g],eff=m.predicted?double(m.observed)/m.predicted:mip::nan;
 table<<std::setprecision(12)<<id<<'\t'<<sipm<<'\t'<<id/100000<<'\t'<<id%100000/10000<<'\t'<<r.decision<<'\t'<<r.reason<<'\t'<<m.predicted<<'\t'<<m.observed<<'\t'<<m.unique<<'\t'<<m.usable<<'\t'<<eff<<'\t'<<(m.predicted?double(m.unique)/m.predicted:mip::nan)<<'\t'<<(m.predicted?std::sqrt(eff*(1-eff)/m.predicted):mip::nan)<<'\t'<<m.duplicate<<'\t'<<m.switched<<'\t'<<m.forced4000<<'\t'<<m.saturated<<'\t'<<m.lg_saturated<<'\t'<<m.gain0<<'\t'<<m.invalid_adc<<'\t'<<m.missing_temperature<<'\t'<<m.invalid_temperature<<'\t'<<m.pedestal<<'\t'<<m.threshold<<'\t'<<m.threshold_sigma<<'\t'<<m.threshold_fallback<<'\t'<<!m.old_fallback<<'\t'<<m.old_mip<<'\t'<<(r.decision==1)<<'\t'<<effective<<'\t'<<effective/m.old_mip<<'\t'<<r.LandauMPV<<'\t'<<r.LandauMPV_error<<'\n';
 for(auto key:{std::make_tuple(sipm,-1,-1,-1),std::make_tuple(sipm,-1,-1,m.old_fallback),std::make_tuple(sipm,id/100000,-1,-1),std::make_tuple(sipm,id/100000,id%100000/10000,-1)}){auto&s=summaryMap[key];++s.channels;s.old_individual+=!m.old_fallback;s.accepted+=r.decision==1;s.undecided+=r.decision==0;s.rejected+=r.decision==2;s.predicted+=m.predicted;s.observed+=m.observed;}}
 summary<<"SiPM_um\tlayer\tchip\told_fallback_class\tchannels\told_individual\taccepted\tundecided\trejected\tnew_fallback\tpredicted\tobserved\n";for(auto&[key,s]:summaryMap){auto[g,l,c,f]=key;summary<<g<<'\t'<<l<<'\t'<<c<<'\t'<<f<<'\t'<<s.channels<<'\t'<<s.old_individual<<'\t'<<s.accepted<<'\t'<<s.undecided<<'\t'<<s.rejected<<'\t'<<s.channels-s.accepted<<'\t'<<s.predicted<<'\t'<<s.observed<<'\n';}
 state<<"SiPM_um\taccepted_donors\tfallback_channels\tfallback_mean_ADC\treader_loadable\treason\n";for(int g=0;g<2;++g)state<<std::setprecision(12)<<(g?10:15)<<'\t'<<donors[g]<<'\t'<<(g?5040:1260)-donors[g]<<'\t'<<means[g]<<'\t'<<ready<<'\t'<<(ready?"ready_for_reader_review":"reader_throws_no_valid_MIP_factors_in_a_group")<<'\n';
 require(bool(schema)&&bool(table)&&bool(summary)&&bool(state),"Failed exporting tables");std::cout<<"schema=PASS rows=6300 accepted15="<<donors[0]<<" accepted10="<<donors[1]<<" reader_loadable="<<ready<<'\n';return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}
